// @ts-nocheck
/**
 * dsh-notifier — unit：配置契约（normalizeConfig / DEFAULT_CONFIG）与免打扰判定
 * （parseHHMM / isInQuietHours）。
 *
 * 覆盖：默认值/部分覆盖/非法值丢弃/未知键透传/默认对象不被污染/
 * 数值范围键（errorMergeWindowMs、askRemindMin、doneMergeWindowMs、
 * historyMaxAgeDays）/quietHours 归一化（HH:MM 校验、allowKinds 白名单）。
 */
import { join } from "node:path";
import { homedir, tmpdir } from "node:os";
import { mkdtempSync, rmSync } from "node:fs";
import { assert } from "./helpers.ts";
import { normalizeConfig, parseHHMM, isInQuietHours, DEFAULT_CONFIG, configFile, historyFile, toastScriptPath } from "../src/index.ts";

const work = mkdtempSync(join(tmpdir(), "dnotify-unit-config-"));
try {
  const DEFAULT_CONFIG_UNTOUCHED = JSON.parse(JSON.stringify(DEFAULT_CONFIG));

  // 路径契约（config.ts 导出）：configFile 是存量自建 json 的迁移源路径（issue #76 后
  // 配置走官方 settings 存储，configFile 不再读写，仅迁移读取/改名）；historyFile 与
  // toast 脚本路径不变。
  assert.equal(configFile(), join(homedir(), ".dsh", "dsh-notifier.json"), "配置迁移源路径固定到 ~/.dsh/dsh-notifier.json");
  assert.equal(historyFile(), join(homedir(), ".dsh", "dsh-notifier-history.jsonl"), "历史路径固定到 ~/.dsh/dsh-notifier-history.jsonl");
  assert.ok(toastScriptPath().endsWith("toast.ps1"), "toast 脚本路径固定到 toast.ps1（src 插桩形态下随加载源解析到 src/）");

  assert.equal(normalizeConfig(undefined).notifyAsk, true);
  // DEFAULT_CONFIG 全字段默认值锁定（对照 config.ts 幸存 BooleanLiteral：
  // 默认值翻转的存活变异体由显式默认断言杀灭）
  assert.equal(DEFAULT_CONFIG.notifyTaskError, true, "默认错误通知开启");
  assert.equal(DEFAULT_CONFIG.notifyTurnEnd, false, "默认轮结束通知关闭");
  assert.equal(DEFAULT_CONFIG.systemNotify, true, "默认系统通知开启");
  assert.equal(DEFAULT_CONFIG.browserNotify, true, "默认浏览器通知开启");
  assert.equal(DEFAULT_CONFIG.notifySound, true, "默认提示音开启");
  const merged = normalizeConfig({ notifyAsk: false, bogus: 1, quietHours: { enabled: true, start: "23:30", end: "06:00", x: 1 } });
  assert.equal(merged.notifyAsk, false);
  assert.equal(merged.notifyTaskDone, true);
  assert.equal(merged.quietHours.enabled, true);
  assert.equal(merged.quietHours.start, "23:30");
  assert.equal(merged.bogus, 1, "未知键透传保留（防降级丢键）");
  assert.equal(normalizeConfig({ quietHours: { start: "25:00" } }).quietHours.start, "22:00", "非法 HH:MM(25:00) 丢弃回默认");
  assert.equal(normalizeConfig({ quietHours: { start: "9:30" } }).quietHours.start, "22:00", "非两位 HH:MM 丢弃");
  assert.equal(normalizeConfig({ notifyAsk: "yes" }).notifyAsk, true, "非布尔丢弃");
  assert.equal(normalizeConfig({ notifyWhenVisible: true }).notifyWhenVisible, true, "页面可见也弹可配置");
  assert.equal(normalizeConfig({ notifyWhenVisible: "x" }).notifyWhenVisible, false, "非布尔丢弃");
  assert.equal(normalizeConfig({ notifyQuestion: false }).notifyQuestion, false, "提问通知可配置");
  assert.equal(normalizeConfig({ notifyQuestion: "x" }).notifyQuestion, true, "非布尔丢弃回默认");
  assert.equal(DEFAULT_CONFIG_UNTOUCHED.quietHours.enabled, false, "normalizeConfig 不污染默认配置");
  assert.equal(normalizeConfig({ errorMergeWindowMs: 5000 }).errorMergeWindowMs, 5000, "合并窗口可配置");
  assert.equal(normalizeConfig({ errorMergeWindowMs: -1 }).errorMergeWindowMs, DEFAULT_CONFIG.errorMergeWindowMs, "非法窗口丢弃");
  assert.equal(normalizeConfig({ errorMergeWindowMs: "x" }).errorMergeWindowMs, DEFAULT_CONFIG.errorMergeWindowMs, "非数字窗口丢弃");
  assert.equal(DEFAULT_CONFIG.notifySubagentDone, false, "子代理完成通知默认关闭");
  assert.equal(normalizeConfig({ notifySubagentDone: true }).notifySubagentDone, true, "子代理完成可配置");
  assert.equal(normalizeConfig({ notifySubagentDone: "x" }).notifySubagentDone, false, "非布尔丢弃回默认");

  assert.equal(parseHHMM("22:00"), 1320);
  assert.equal(parseHHMM("08:30"), 510);
  assert.ok(Number.isNaN(parseHHMM("8:30")));
  assert.ok(Number.isNaN(parseHHMM("25:00")));

  assert.equal(isInQuietHours(new Date(2026, 0, 1, 23, 0), { enabled: true, start: "22:00", end: "08:00" }), true, "跨午夜晚间");
  assert.equal(isInQuietHours(new Date(2026, 0, 1, 7, 0), { enabled: true, start: "22:00", end: "08:00" }), true, "跨午夜凌晨");
  assert.equal(isInQuietHours(new Date(2026, 0, 1, 12, 0), { enabled: true, start: "22:00", end: "08:00" }), false, "中午不静默");
  assert.equal(isInQuietHours(new Date(2026, 0, 1, 12, 0), { enabled: false, start: "22:00", end: "08:00" }), false, "禁用");
  assert.equal(isInQuietHours(new Date(2026, 0, 1, 9, 0), { enabled: true, start: "09:00", end: "17:00" }), true, "同日内");
  assert.equal(isInQuietHours(new Date(2026, 0, 1, 8, 0), { enabled: true, start: "09:00", end: "17:00" }), false);

  // M4 配置归一化：askRemindMin / quietHours.allowKinds
  assert.equal(normalizeConfig({ askRemindMin: 3 }).askRemindMin, 3, "审批提醒分钟可配");
  assert.equal(normalizeConfig({ askRemindMin: 0 }).askRemindMin, 0, "0=关闭审批提醒");
  assert.equal(normalizeConfig({ askRemindMin: "x" }).askRemindMin, DEFAULT_CONFIG.askRemindMin, "非法提醒分钟回默认 5");
  assert.deepEqual(normalizeConfig({ quietHours: { allowKinds: ["ask", "bogus", "error"] } }).quietHours.allowKinds, ["ask", "error"], "allowKinds 白名单过滤");

  // 合并/清理配置：doneMergeWindowMs / errorMergeWindowMs(0=关) / historyMaxAgeDays
  assert.equal(normalizeConfig({ doneMergeWindowMs: 0 }).doneMergeWindowMs, 0, "完成聚合窗口 0=关闭");
  assert.equal(normalizeConfig({ doneMergeWindowMs: 1500 }).doneMergeWindowMs, 1500, "完成聚合窗口可配");
  assert.equal(normalizeConfig({ doneMergeWindowMs: "x" }).doneMergeWindowMs, DEFAULT_CONFIG.doneMergeWindowMs, "非法完成窗口回默认");
  assert.equal(normalizeConfig({ errorMergeWindowMs: 0 }).errorMergeWindowMs, 0, "错误合并窗口 0=关闭");
  assert.equal(normalizeConfig({ errorMergeWindowMs: -1 }).errorMergeWindowMs, DEFAULT_CONFIG.errorMergeWindowMs, "负数错误窗口回默认");
  assert.equal(normalizeConfig({ historyMaxAgeDays: 30 }).historyMaxAgeDays, 30, "按天清理可配");
  assert.equal(normalizeConfig({ historyMaxAgeDays: 0 }).historyMaxAgeDays, 0, "按天清理 0=关");

  // #330 SSE 连接上限：默认 16，范围 1~1024，非法值丢弃回默认；未知键透传排除表不吞它
  assert.equal(DEFAULT_CONFIG.maxConnections, 16, "maxConnections 默认 16");
  assert.equal(normalizeConfig(undefined).maxConnections, 16, "无输入回默认 16");
  assert.equal(normalizeConfig({ maxConnections: 8 }).maxConnections, 8, "上限可配");
  assert.equal(normalizeConfig({ maxConnections: 1 }).maxConnections, 1, "下限 1 可配");
  assert.equal(normalizeConfig({ maxConnections: 0 }).maxConnections, DEFAULT_CONFIG.maxConnections, "0 非法回默认");
  assert.equal(normalizeConfig({ maxConnections: -3 }).maxConnections, DEFAULT_CONFIG.maxConnections, "负数非法回默认");
  assert.equal(normalizeConfig({ maxConnections: 1025 }).maxConnections, DEFAULT_CONFIG.maxConnections, "超上界 1024 非法回默认");
  assert.equal(normalizeConfig({ maxConnections: 16.6 }).maxConnections, 17, "小数取整");
  assert.equal(normalizeConfig({ maxConnections: "8" }).maxConnections, DEFAULT_CONFIG.maxConnections, "字符串非法回默认");
  assert.equal(normalizeConfig({ maxConnections: 4, bogus: 1 }).bogus, 1, "未知键仍透传（排除表不吞其他键）");
} finally {
  rmSync(work, { recursive: true, force: true });
}

packages/dsh-notifier/test/unit-sanitize.source:
// @ts-nocheck
/**
 * dsh-notifier — unit：错误文本脱敏（sanitizeErrorText）。
 *
 * 覆盖：路径/令牌/密钥打码 + 截断；issue #6 扩展（GitHub PAT / PEM 私钥 /
 * 连接串凭据 / 邮箱）；规则顺序硬约束回归；FP 证伪回归（已删规则的误伤
 * 形态必须保持原样）；性能护栏（防灾难性回溯）；PEM 限窗/赋值分隔符/amqps
 * 评审修复回归。
 */
import { assert } from "./helpers.ts";
import { sanitizeErrorText } from "../src/index.ts";

// 路径/令牌/密钥打码 + 截断
assert.equal(sanitizeErrorText("failed /home/me/dev/x.yaml: EACCES"), "failed <path>: EACCES", "用户路径打码");
assert.equal(sanitizeErrorText("token: 3f9a2b7c4d5e6f708192a3b4c5d6e7f8091a2b3c4d"), "token: <token>", "长 hex 令牌打码");
assert.ok(!sanitizeErrorText("password=s3cr3t").includes("s3cr3t"), "密钥赋值掩蔽");
assert.equal(sanitizeErrorText("错".repeat(500)).length, 300, "截断 300");
assert.equal(sanitizeErrorText("普通错误"), "普通错误", "普通文本原样");
assert.equal(sanitizeErrorText("x".repeat(40)), "<token>", "长重复字符按令牌打码");

// 推送前修复（P1）：脱敏漏网补充——JWT / AKIA 前缀 / /root 路径
assert.equal(
  sanitizeErrorText("Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"),
  "Authorization=<redacted> <token>",
  "Authorization 头掩蔽 + JWT（含 - _ 的 base64url）整段打码"
);
assert.equal(sanitizeErrorText("aws key AKIAIOSFODNN7EXAMPLE used"), "aws key <token> used", "AKIA 前缀密钥打码");
assert.ok(!sanitizeErrorText("Cannot read /root/.ssh/id_rsa: denied").includes("/root"), "/root 路径打码");
assert.ok(!sanitizeErrorText("open /etc/passwd denied").includes("/etc"), "/etc 路径打码");
// 防误伤：普通含下划线/连字符的英文单词不应被 JWT/AKIA 规则误打码
assert.equal(sanitizeErrorText("the-key_is-here and also_fine"), "the-key_is-here and also_fine", "普通文本不被 JWT 规则误伤");

// ---- issue #6 脱敏扩展：GitHub PAT / PEM 私钥 / 连接串凭据 / 邮箱 ----
// GitHub PAT classic（ghp/gho/ghu/ghs/ghr + 恰 36 位字母数字）
const patCore36 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
assert.equal(sanitizeErrorText(`token ghp_${patCore36} end`), "token <token> end", "GitHub PAT classic 打码");
for (const prefix of ["gho", "ghu", "ghs", "ghr"]) {
  assert.equal(sanitizeErrorText(`${prefix}_${patCore36}`), "<token>", `GitHub PAT ${prefix}_ 前缀打码`);
}
// 长度边界锁定：35/37 位不命中（业界共识写死长度），且不被通用长串规则部分命中
assert.equal(sanitizeErrorText(`ghp_${patCore36.slice(0, 35)}`), `ghp_${patCore36.slice(0, 35)}`, "PAT 35 位不误伤");
assert.equal(sanitizeErrorText(`ghp_${patCore36}X`), `ghp_${patCore36}X`, "PAT 37 位不误伤");
// fine-grained PAT（区间长度）
const fgPat = `github_pat_${"A".repeat(22)}_${"B".repeat(59)}`;
assert.equal(sanitizeErrorText(`bad ${fgPat}!`), "bad <token>!", "GitHub fine-grained PAT 打码");
// 回归：通用长串规则不得对 github_pat_ 部分命中产生残缺掩码
assert.ok(!sanitizeErrorText(fgPat).includes("_"), "fine-grained PAT 无残缺残留");

// PEM 私钥：完整块（含 \r\n 变体）与孤立 BEGIN 兜底；证书/PUBLIC KEY 不误伤
const pemBody = "MIIEowIBAAKCAQEA0Z3VS5JJcds3xfn/yGWyifZ6IWVpYFKEzBNGIFfD8hV0v";
assert.equal(
  sanitizeErrorText(`-----BEGIN RSA PRIVATE KEY-----\n${pemBody}\n-----END RSA PRIVATE KEY-----\nok`),
  "<private-key>\nok",
  "PEM 完整私钥块打码"
);
assert.ok(
  !sanitizeErrorText(`-----BEGIN EC PRIVATE KEY-----\r\n${pemBody}\r\n-----END EC PRIVATE KEY-----`).includes("MIIEow"),
  "PEM 私钥块（\\r\\n）打码"
);
assert.ok(
  !sanitizeErrorText(`-----BEGIN OPENSSH PRIVATE KEY-----\nb3BlbnNzaC1rZXktdjEAAAAA\n尾随`).includes("b3BlbnNzaC"),
  "PEM 孤立 BEGIN（无 END，错误消息截断常态）兜底打码"
);
assert.equal(
  sanitizeErrorText("-----BEGIN CERTIFICATE-----\nc2hvcnRib2R5\n-----END CERTIFICATE-----"),
  "-----BEGIN CERTIFICATE-----\nc2hvcnRib2R5\n-----END CERTIFICATE-----",
  "证书块不误伤"
);
assert.ok(!sanitizeErrorText("-----BEGIN PUBLIC KEY-----\nc2hvcnRib2R5\n-----END PUBLIC KEY-----").includes("<private-key>"), "PUBLIC KEY 不误伤");

// 数据库/消息队列连接串凭据：scheme 保留、凭据整体掩蔽
assert.equal(
  sanitizeErrorText("postgres://admin:s3cret@db.local:5432/app down"),
  "postgres://<redacted>@db.local:5432/app down",
  "postgres 连接串掩蔽且 scheme 正确（防 $1 组号回归）"
);
assert.equal(sanitizeErrorText("redis://:MyPass@127.0.0.1:6379"), "redis://<redacted>@127.0.0.1:6379", "redis 空用户名形态掩蔽");
assert.equal(
  sanitizeErrorText("mongodb+srv://dev:pw123@cluster0.abc12.mongodb.net/test"),
  "mongodb+srv://<redacted>@cluster0.abc12.mongodb.net/test",
  "mongodb+srv 连接串掩蔽"
);
assert.equal(sanitizeErrorText("POSTGRES://U:P@H"), "POSTGRES://<redacted>@H", "大写 scheme 掩蔽（i flag）");
assert.equal(
  sanitizeErrorText("jdbc:mysql://host/db?user=root&password=topsecret"),
  "jdbc:mysql://host/db?user=root&password=<redacted>",
  "JDBC 凭据在 query 参数，由密钥赋值规则覆盖"
);
assert.equal(sanitizeErrorText("postgres://u:p@ss@h"), "postgres://<redacted>@ss@h", "畸形双 @ 锁定残缺行为（URL 规范要求编码）");

// 邮箱（严格版）：正常邮箱打码；资源引用/版本号不误伤
assert.equal(sanitizeErrorText("mail a.b-c@example.co.uk end"), "mail <email> end", "邮箱打码");
assert.equal(sanitizeErrorText("loaded image@2x.png"), "loaded image@2x.png", "资源引用 @2x 不误伤");
assert.equal(sanitizeErrorText("need @scope/pkg@1.2.3"), "need @scope/pkg@1.2.3", "包版本 pkg@1.2.3 不误伤");
// 顺序回归：DSN 掩蔽后占位符不得被邮箱规则二次命中产生 <<email>>
assert.equal(
  sanitizeErrorText("mysql://admin:s3cret@db.example.com down"),
  "mysql://<redacted>@db.example.com down",
  "DSN 与邮箱规则顺序回归"
);
// 尖括号引用形态（issue #30）：双断言放行 <user@host>，不再整体漏网
assert.equal(
  sanitizeErrorText("From: John <john.doe@corp.example.com> signed"),
  "From: John <<email>> signed",
  "尖括号包裹的真实邮箱正常打码"
);
// 占位符不被二次破坏（issue #30）：裸 <redacted>@真实域名 形态必须原样保留
assert.equal(
  sanitizeErrorText("<redacted>@db.example.com down"),
  "<redacted>@db.example.com down",
  "DSN 掩码占位符不被邮箱规则二次命中"
);

// 规则顺序硬约束回归
assert.equal(
  sanitizeErrorText("postgres://u:eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c@h"),
  "postgres://<redacted>@h",
  "DSN 先于 JWT：连接串内嵌 JWT 整体掩蔽，用户名不残留"
);
assert.equal(
  sanitizeErrorText("postgres://u:token@hostname down"),
  "postgres://<redacted>@hostname down",
  "DSN 先于密钥赋值：host 保留、凭据不劣化残留"
);

// 边界与容错：Symbol 入参不抛错；截断窗口腰斩行为锁定
assert.doesNotThrow(() => sanitizeErrorText(Symbol("x")), "Symbol 入参不抛 TypeError");
assert.equal(sanitizeErrorText(Symbol("x")), "Symbol(x)", "Symbol 入参转字符串");
assert.equal(sanitizeErrorText("前".repeat(296) + `ghp_${patCore36}`), "前".repeat(296) + "<tok", "占位符落在截断窗口被腰斩（锁定行为）");

// FP 证伪回归：已删除规则的高频误伤形态必须保持原样（防止将来加回来）
assert.equal(sanitizeErrorText("Date.now()=1718000000000"), "Date.now()=1718000000000", "13 位毫秒时间戳原样（信用卡规则证伪）");
assert.equal(sanitizeErrorText("Chrome/120.0.0.0 Safari/537.36"), "Chrome/120.0.0.0 Safari/537.36", "UA 版本号原样（IPv4 规则证伪）");
assert.equal(sanitizeErrorText("order 1234567890123456 paid"), "order 1234567890123456 paid", "16 位订单号原样");

// 性能护栏：大文本全链无灾难性回溯（宽松上限防 CI 抖动，非基准测试）
{
  const big = "postgres://admin:s3cret@db.example.com error jwt eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpM\n".repeat(10000);
  const t0 = Date.now();
  sanitizeErrorText(big);
  const cost = Date.now() - t0;
  assert.ok(cost < 1000, `约 1MB 文本脱敏耗时 ${cost}ms < 1000ms（防回溯退化）`);
}

// 性能护栏（对抗形态）：多 BEGIN 无 END 输入曾因完整块规则 O(k·n) 阻塞宿主数秒
// （评审实测 1MB 高密度 BEGIN 6-17s），限窗 {0,4096} 后必须保持线性量级
{
  const adversarial = "-----BEGIN PRIVATE KEY-----".repeat(20000); // 约 560KB
  const t0 = Date.now();
  const out = sanitizeErrorText(adversarial);
  const cost = Date.now() - t0;
  assert.ok(cost < 5000, `对抗输入（2 万 BEGIN 无 END）脱敏耗时 ${cost}ms < 5000ms（防 PEM 回溯回归）`);
  assert.ok(out.startsWith("<private-key>"), "对抗输入由孤立 BEGIN 兜底规则接住");
}

// ---- 评审修复回归：PEM 限窗 / 赋值分隔符收紧 / amqps ----

// PEM 完整块在窗口内仍整体打码；超窗伪块由孤立 BEGIN 兜底接住
{
  const pad = "A".repeat(5000);
  assert.equal(
    sanitizeErrorText(`-----BEGIN RSA PRIVATE KEY-----\n${pad}\n-----END RSA PRIVATE KEY-----\nok`),
    "<private-key>",
    "PEM 超 4096 窗口的真实长块：完整块失配后由兜底规则整体掩蔽到文本尾"
  );
  assert.equal(
    sanitizeErrorText("前 -----BEGIN PRIVATE KEY-----\nMIIEow\n-----END RSA PRIVATE KEY----- 后续可读"),
    "前 <private-key> 后续可读",
    "PEM 窗口内完整块打码且块后内容保留可读"
  );
}

// 密钥赋值规则：分隔符 [=:] 必须显式——自然语言不得误伤（评审 P1 回归）
assert.equal(sanitizeErrorText("auth failed: token expired"), "auth failed: token expired", "自然语言 token expired 不误伤");
assert.equal(sanitizeErrorText("request rejected: invalid token provided"), "request rejected: invalid token provided", "invalid token provided 不误伤");
assert.equal(sanitizeErrorText("password policy requires changes"), "password policy requires changes", "password policy 不误伤");
assert.equal(sanitizeErrorText("Authorization header missing"), "Authorization header missing", "Authorization header 不误伤");
// 显式赋值形态仍打码（含「键名: 空格 值」与引号形态）
assert.equal(sanitizeErrorText("token: abc123"), "token=<redacted>", "显式冒号赋值仍打码");
assert.equal(sanitizeErrorText('password = "s3cr3t"'), 'password=<redacted>"', "等号带空格+引号赋值仍打码（收尾引号残留为已知形态）");
assert.ok(!sanitizeErrorText("api_key=sk-live-9f8e7d6c5b4a").includes("sk-live"), "api_key= 赋值仍打码");

// amqps 连接串凭据：scheme 保留、凭据整体掩蔽（评审 P2 回归，不再半脱敏）
assert.equal(sanitizeErrorText("amqps://guest:guest@rabbit.local/vhost"), "amqps://<redacted>@rabbit.local/vhost", "amqps 连接串整体掩蔽");
assert.equal(sanitizeErrorText("AMQPS://u:p@h/v"), "AMQPS://<redacted>@h/v", "amqps 大写 scheme 掩蔽");

packages/dsh-notifier/test/unit-text.src.source:
// @ts-nocheck
/**
 * dsh-notifier — unit：通知文案与系统命令构造纯函数。
 *
 * 覆盖：formatDuration 人类可读耗时、prettyToolName（中文映射 / MCP 美化 /
 * 未知原样）、sessionTitleOf（标题提取/截断/容错）、buildSystemCommand
 * （Windows/macOS/Linux 参数形态）、isLoopbackRequest 围栏判定。
 */
import { assert, fakeReq } from "./helpers.ts";
import { formatDuration, prettyToolName, sessionTitleOf, buildSystemCommand, isLoopbackRequest } from "../src/index.ts";

assert.equal(formatDuration(45000), "45 秒");
assert.equal(formatDuration(135000), "2 分 15 秒");
assert.equal(formatDuration(3725000), "1 小时 2 分 5 秒");
assert.equal(formatDuration(0), "0 秒");

assert.equal(prettyToolName("pwsh"), "PowerShell 命令", "常见工具映射中文名");
assert.equal(prettyToolName("ssh_exec"), "SSH 远程执行");
assert.equal(prettyToolName("web_search"), "联网搜索");
assert.equal(prettyToolName("unknown_tool"), "unknown_tool", "未知工具原样");
assert.equal(prettyToolName("mcp__my-server__read_file"), 'MCP 服务器 "my-server" 的工具 "read_file"');
assert.equal(prettyToolName("mcp__srv__a__b"), 'MCP 服务器 "srv" 的工具 "a__b"');
assert.equal(prettyToolName(undefined), "?");

// buildSystemCommand：Windows/macOS/Linux 参数形态（smoke 断言 spawn 参数）
// Windows（issue #238）：固定前缀 + 单一 base64 payload token；前缀用 deepEqual
// 全序列快照（includes 片段断言抓不住多余/错位 token）。
const decodePayload = (argv: string[]) => JSON.parse(Buffer.from(argv[argv.length - 1], "base64").toString("utf8"));
const winArgs = buildSystemCommand("win32", "标题", "内容 -x", { silent: true, toastScript: "t.ps1" });
assert.equal(winArgs[winArgs.length - 2], "-Payload", "payload 参数名成对出现在末尾");
assert.deepEqual(
  winArgs.slice(0, -2),
  ["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", "t.ps1"],
  "win32 argv 固定前缀快照（末两位为 -Payload + 值）"
);
assert.match(winArgs[winArgs.length - 1], /^[A-Za-z0-9+/=]+$/, "payload 仅含 base64 字符集（永不被误认成参数名/不被拆 token）");
assert.deepEqual(decodePayload(winArgs), { title: "标题", message: "内容 -x", silent: true }, "payload round-trip 深等于输入");
// 边界用例：dash 开头 / 双引号 / 换行 / emoji——payload 形态不变、内容无损往返
for (const c of [
  { title: "-TODO-fix", message: "- item", silent: true },
  { title: '说"话', message: "line\nbreak", silent: false },
  { title: "🚀任务完成", message: "🎉🎉🎉", silent: true },
]) {
  const a = buildSystemCommand("win32", c.title, c.message, { silent: c.silent, toastScript: "t.ps1" });
  assert.match(a[a.length - 1], /^[A-Za-z0-9+/=]+$/, "边界值下 payload 仍是纯 base64 token");
  assert.deepEqual(decodePayload(a), c, "边界值 round-trip 无损");
}
const macArgs = buildSystemCommand("darwin", "标题", '说"话', { silent: false, toastScript: "t.ps1" });
assert.equal(macArgs[0], "osascript");
assert.match(macArgs.join(" "), /display notification/);
assert.ok(macArgs.join(" ").includes('sound name "Glass"'), "非静默带 Glass 提示音");
assert.ok(!macArgs.join(" ").includes('说话"'), "消息内引号被转义");
assert.equal(buildSystemCommand("linux", "t", "m", { silent: true, notifySendAvailable: false, toastScript: "t.ps1" }), null, "notify-send 不可用返回 null");
assert.deepEqual(buildSystemCommand("linux", "t", "m", { silent: true, toastScript: "t.ps1" }), ["notify-send", "t", "m"]);

// sessionTitleOf：从 session.events 的 session/title 事件取标题
const titledAgent = {
  id: "session-1",
  session: { events: [{ type: "other", data: {} }, { type: "session/title", data: { title: "优化 notifier 插件" } }] },
};
assert.equal(sessionTitleOf(titledAgent), "优化 notifier 插件", "取最后一个标题事件");
assert.equal(sessionTitleOf({ id: "session-1", session: { events: [] } }), undefined, "无标题事件返回 undefined");
assert.equal(sessionTitleOf({ id: "session-1" }), undefined, "无 session 返回 undefined");
assert.equal(sessionTitleOf(undefined), undefined, "无 agent 返回 undefined");
assert.equal(sessionTitleOf({ id: "session-1", session: { events: "bad" } }), undefined, "events 非数组容错");
assert.equal(
  sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: "优".repeat(80) } }] } }),
  "优".repeat(40),
  "标题截断 40 字符"
);

// sessionTitleOf 接入脱敏链（issue #30）：标题源自会话内容，进入通知与历史前
// 敏感片段必须打码；正常标题不含敏感特征、脱敏后原样透传保持可读
assert.ok(
  !sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: `修复 ${"a".repeat(48)} 泄漏` } }] } })!.includes("aaaa"),
  "标题中长 hex 密钥片段被打码为 <token>"
);
assert.equal(
  sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: `修复 ${"f".repeat(30)} 泄漏` } }] } }),
  "修复 <token> 泄漏",
  "≥24 位 hex 长串在标题中打码"
);
assert.ok(
  !sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: "联系 admin@corp.example.com 处理部署" } }] } })!.includes("admin@"),
  "标题中邮箱地址被打码为 <email>"
);
assert.equal(
  sessionTitleOf(titledAgent),
  "优化 notifier 插件",
  "正常标题脱敏后原样透传（可读性不受影响）"
);

// loopback 围栏：回环放行、非回环拒绝
assert.equal(isLoopbackRequest(fakeReq()), true);
assert.equal(isLoopbackRequest(fakeReq({ socket: { remoteAddress: "10.0.0.2" } })), false);
